// Copyright (c) HashiCorp, Inc.
// SPDX-License-Identifier: BUSL-1.1

package terraform

import (
	"fmt"
	"log"

	"github.com/hashicorp/terraform/internal/addrs"
	"github.com/hashicorp/terraform/internal/configs"
)

// GraphNodeAttachResourceConfig is an interface that must be implemented by nodes
// that want resource configurations attached.
type GraphNodeAttachResourceConfig interface {
	GraphNodeConfigResource

	// Sets the configuration, either to a present resource block or to
	// a "removed" block commemorating a resource that has since been
	// removed. Callers should always leave at least one of these
	// arguments set to nil.
	AttachResourceConfig(*configs.Resource, *configs.Removed)
}

// AttachResourceConfigTransformer goes through the graph and attaches
// resource configuration structures to nodes that implement
// GraphNodeAttachManagedResourceConfig or GraphNodeAttachDataResourceConfig.
//
// The attached configuration structures are directly from the configuration.
// If they're going to be modified, a copy should be made.
type AttachResourceConfigTransformer struct {
	Config *configs.Config // Config is the root node in the config tree
}

func (t *AttachResourceConfigTransformer) Transform(g *Graph) error {
	vertices := g.Vertices()
	nVertices := len(vertices)
	type attachCandidate struct {
		vertex interface{}
		arn    GraphNodeAttachResourceConfig
		addr   addrs.ConfigResource
		name   string
	}
	candidates := make([]attachCandidate, 0, nVertices)
	for _, v := range vertices {
		arn, isAttach := v.(GraphNodeAttachResourceConfig)
		if isAttach {
			vertexName := fmt.Sprintf("%v", v)
			if named, namedOK := v.(interface{ Name() string }); namedOK {
				vertexName = named.Name()
			} else {
				if stringer, stringerOK := v.(fmt.Stringer); stringerOK {
					vertexName = stringer.String()
				}
			}
			candidates = append(candidates, attachCandidate{
				vertex: v,
				arn:    arn,
				addr:   arn.ResourceAddr(),
				name:   vertexName,
			})
		}
	}

	for _, candidate := range candidates {
		v := candidate.vertex
		arn := candidate.arn
		addr := candidate.addr
		vertexName := candidate.name
		resAddr := addr.Resource
		resMode := resAddr.Mode
		resType := resAddr.Type
		resName := resAddr.Name
		modPath := addr.Module
		selectedKey := ""

		var lookupKey string
		switch resMode {
		case addrs.ManagedResourceMode:
			if resType != "" {
				if resName != "" {
					lookupKey = resType + "." + resName
				} else {
					lookupKey = resType + "."
				}
			} else {
				if resName != "" {
					lookupKey = "." + resName
				} else {
					lookupKey = "."
				}
			}
		case addrs.DataResourceMode:
			if resType != "" {
				if resName != "" {
					lookupKey = "data." + resType + "." + resName
				} else {
					lookupKey = "data." + resType + "."
				}
			} else {
				if resName != "" {
					lookupKey = "data.." + resName
				} else {
					lookupKey = "data.."
				}
			}
		case addrs.InvalidResourceMode:
			if resType != "" {
				if resName != "" {
					lookupKey = "<invalid>." + resType + "." + resName
				} else {
					lookupKey = "<invalid>." + resType + "."
				}
			} else {
				if resName != "" {
					lookupKey = "<invalid>.." + resName
				} else {
					lookupKey = "<invalid>.."
				}
			}
		default:
			if resType != "" {
				if resName != "" {
					lookupKey = "<invalid>." + resType + "." + resName
				} else {
					lookupKey = "<invalid>." + resType + "."
				}
			} else {
				if resName != "" {
					lookupKey = "<invalid>.." + resName
				} else {
					lookupKey = "<invalid>.."
				}
			}
		}
		selectedKey = lookupKey

		rootCfg := t.Config
		var config *configs.Config
		modPathLen := len(modPath)
		if modPathLen == 0 {
			config = rootCfg
		} else {
			current := rootCfg
			walkFailed := false
			pathSteps := make([]string, modPathLen)
			for stepCopyIdx := 0; stepCopyIdx < modPathLen; stepCopyIdx++ {
				pathSteps[stepCopyIdx] = modPath[stepCopyIdx]
			}
			stepCount := len(pathSteps)
			assembled := make([]string, 0, stepCount)
			for stepIdx := 0; stepIdx < stepCount; stepIdx++ {
				stepName := pathSteps[stepIdx]
				children := current.Children
				if children == nil {
					walkFailed = true
					current = nil
					break
				}
				foundChild := false
				for childName, child := range children {
					if childName == stepName {
						if child != nil {
							current = child
							assembled = append(assembled, stepName)
							foundChild = true
							break
						}
						current = nil
						foundChild = true
						break
					}
				}
				if !foundChild {
					walkFailed = true
					current = nil
					break
				}
				if current == nil {
					walkFailed = true
					break
				}
			}
			if !walkFailed {
				if len(assembled) == stepCount {
					config = current
				} else {
					config = nil
				}
			}
		}

		if config != nil {
			mod := config.Module
			var found *configs.Resource
			switch resMode {
			case addrs.ManagedResourceMode:
				managed := mod.ManagedResources
				if managed != nil {
					managedLen := len(managed)
					if managedLen == 0 {
						found = nil
					} else {
						matched := false
						for key, r := range managed {
							if key == selectedKey {
								found = r
								matched = true
								break
							}
						}
						if !matched {
							found = nil
						}
					}
				} else {
					found = nil
				}
			case addrs.DataResourceMode:
				data := mod.DataResources
				if data != nil {
					dataLen := len(data)
					if dataLen == 0 {
						found = nil
					} else {
						matched := false
						for key, r := range data {
							if key == selectedKey {
								found = r
								matched = true
								break
							}
						}
						if !matched {
							found = nil
						}
					}
				} else {
					found = nil
				}
			case addrs.InvalidResourceMode:
				found = nil
			default:
				found = nil
			}

			if found != nil {
				foundRange := found.DeclRange
				log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) config from %#v", vertexName, v, foundRange)
				arn.AttachResourceConfig(found, nil)
				if gnapmc, ok := v.(GraphNodeAttachProviderMetaConfigs); ok {
					log.Printf("[TRACE] AttachResourceConfigTransformer: attaching provider meta configs to %s", vertexName)
					providerMetas := mod.ProviderMetas
					if providerMetas != nil {
						gnapmc.AttachProviderMetaConfigs(providerMetas)
					} else {
						log.Printf("[TRACE] AttachResourceConfigTransformer: no provider meta configs available to attach to %s", vertexName)
					}
				}
			}

			removedBlocks := mod.Removed
			if removedBlocks != nil {
				for _, rem := range removedBlocks {
					switch subj := rem.From.RelSubject.(type) {
					case addrs.Module:
						// Not for a resource at all, so can't possibly match
					case addrs.ConfigResource:
						fromRes := subj.Resource
						fromMode := fromRes.Mode
						fromType := fromRes.Type
						fromName := fromRes.Name
						if fromMode == resMode {
							if fromType == resType {
								if fromName == resName {
									removedRange := rem.DeclRange
									log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) removed block from %#v", vertexName, v, removedRange)

									// Validation ensures that there can't be both a resource/data block
									// and a removed block referring to the same configuration, so
									// we can assume that this isn't clobbering a non-removed resource
									// configuration we already attached above.
									arn.AttachResourceConfig(nil, rem)
								}
							}
						}
					default:
						// Not for a resource at all, so can't possibly match
					}
				}
			}
		} else {
			log.Printf("[TRACE] AttachResourceConfigTransformer: %q (%T) has no configuration available", vertexName, v)
		}
	}

	return nil
}

